L000292	\subsection{Ladder product of Bell pairs} \label{app:ladder_Bell}
L000293	
L000294	Consider a square lattice in $D=2$ dimensions, with $N_x$ qubits along the $x$-direction and $N_y = 2$ qubits along the $y$-direction [i.e., a ladder; see Fig. \ref{fig:products_of_Bell_pairs} (left)]. We define the ladder product of Bell pairs as the state: \begin{equation} \ket{\Psi^{\rm ladder-BP}} = \bigotimes_{x=0}^{N_x - 1} \ket{\psi (\theta_{x,0}, \theta_{x,1})}_{(x,0),(x,1)} , \label{eq:product_Bell_pairs} \end{equation} where $\ket{\psi (\theta_{x,0}, \theta_{x,1})}_{(x,0),(x,1)}$ is a Bell pair for the two qubits on a rung of the ladder [i.e., at lattice sites $(x,0)$ and $(x,1)$] and $\theta_{x,0} \in \{ \pm 1 \}$, $\theta_{x,1} \in \{ \pm 1 \}$. This is a stabilizer state with the stabilizer group: \begin{equation} \mathcal{S}^{\rm ladder-BP} = \langle \{ \theta_{x,0} \hat{\sigma}_{x,0}^X \hat{\sigma}_{x,1}^X,  \theta_{x,1} \hat{\sigma}_{x,0}^Z \hat{\sigma}_{x,1}^Z \}_{x=0}^{N_x - 1} \rangle . \end{equation} The generators $\theta_{x,0} \hat{\sigma}_{x,0}^X \hat{\sigma}_{x,1}^X$ and $\theta_{x,1} \hat{\sigma}_{x,0}^Z \hat{\sigma}_{x,1}^Z$ are illustrated in Fig. \ref{fig:products_of_Bell_pairs} (left).
L000295	
L000296	In Table \ref{table:product_Bell_pairs} we list all of the $(2,2,2)$-factorizable stabilizer elements of $\mathcal{S}^{\rm ladder-BP}$, along with the corresponding $2$-local, $2$-body Hermitian operators that annihilate the stabilizer state. By Result \ref{result:main}, the 2-local, 2-body parent Hamiltonian for the ladder product of Bell pairs is a linear combination of all terms in the right column of Table \ref{table:product_Bell_pairs}, and is given by $\hat{H}^{\rm ladder-BP} = \hat{H}_h + \hat{H}_\updownarrow + \hat{H}_\leftrightarrow$ where: \begin{eqnarray} \hat{H}_h &=& \sum_{x=0}^{N_x - 1} [ h_{x}^X (\hat{\sigma}_{x,0}^X - \theta_{x,0} \hat{\sigma}_{x,1}^X) + h_{x}^Y (\hat{\sigma}_{x,0}^Y + \theta_{x,0} \theta_{x,1} \hat{\sigma}_{x,1}^Y) + h_{x}^Z (\hat{\sigma}_{x,0}^Z - \theta_{x,1} \hat{\sigma}_{x,1}^Z) ] \label{eq:H_h} \\ \hat{H}_\updownarrow &=& \sum_{x=0}^{N_x-1} [ J_{x}^{XX} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x,1}^X - \theta_{x,0}\theta_{x+1,0} \hat{\sigma}_{x+1,0}^X \hat{\sigma}_{x+1,1}^X) + J_{x}^{YY} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x,1}^Y - \theta_{x,0}\theta_{x,1}\theta_{x+1,0}\theta_{x+1,1} \hat{\sigma}_{x+1,0}^Y \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + J_{x}^{ZZ} (\hat{\sigma}_{x,0}^Z \hat{\sigma}_{x,1}^Z - \theta_{x,1}\theta_{x+1,1} \hat{\sigma}_{x+1,0}^Z \hat{\sigma}_{x+1,1}^Z) + J_{x}^{XZ} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x,1}^X - \theta_{x,0}\theta_{x+1,1} \hat{\sigma}_{x+1,0}^Z \hat{\sigma}_{x+1,1}^Z) \nonumber \\ && \qquad + J_{x}^{ZX} (\hat{\sigma}_{x,0}^Z \hat{\sigma}_{x,1}^Z - \theta_{x,1}\theta_{x+1,0} \hat{\sigma}_{x+1,0}^X \hat{\sigma}_{x+1,1}^X) + J_{x}^{XY} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x,1}^X + \theta_{x,0}\theta_{x+1,0}\theta_{x+1,1} \hat{\sigma}_{x+1,0}^Y \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + J_{x}^{YX} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x,1}^Y + \theta_{x,0}\theta_{x,1}\theta_{x+1,0} \hat{\sigma}_{x+1,0}^X \hat{\sigma}_{x+1,1}^X ) + J_{x}^{ZY} ( \hat{\sigma}_{x,0}^Z \hat{\sigma}_{x,1}^Z + \theta_{x,1}\theta_{x+1,0} \theta_{x+1,1} \hat{\sigma}_{x+1,0}^Y \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + J_{x}^{YZ} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x,1}^Y + \theta_{x,0}\theta_{x,1}\theta_{x+1,1} \hat{\sigma}_{x+1,0}^Z \hat{\sigma}_{x+1,1}^Z) ] \label{eq:H_updown} \\ \hat{H}_{\leftrightarrow} &=& \sum_{x=0}^{N_x-1} [ \tilde{J}_{x}^{XX} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x+1,0}^X - \theta_{x,0}\theta_{x+1,0} \hat{\sigma}_{x,1}^X \hat{\sigma}_{x+1,1}^X) + \tilde{J}_{x}^{YY} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x+1,0}^Y - \theta_{x,0}\theta_{x,1}\theta_{x,1}\theta_{x+1,1} \hat{\sigma}_{x+1,1}^Y \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + \tilde{J}_{x}^{ZZ} (\hat{\sigma}_{x,0}^Z \hat{\sigma}_{x+1,0}^Z - \theta_{x,1}\theta_{x,1} \hat{\sigma}_{x+1,1}^Z \hat{\sigma}_{x+1,1}^Z) + \tilde{J}_{x}^{XZ} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x+1,0}^Z - \theta_{x,0}\theta_{x+1,1} \hat{\sigma}_{x,1}^X \hat{\sigma}_{x+1,1}^Z) \nonumber \\ && \qquad + \tilde{J}_{x}^{ZX} (\hat{\sigma}_{x,0}^Z \hat{\sigma}_{x+1,0}^X - \theta_{x,1}\theta_{x+1,0} \hat{\sigma}_{x,1}^Z \hat{\sigma}_{x+1,1}^X) + \tilde{J}_{x}^{XY} (\hat{\sigma}_{x,0}^X \hat{\sigma}_{x+1,0}^Y + \theta_{x,0}\theta_{x+1,0}\theta_{x+1,1} \hat{\sigma}_{x,1}^X \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + \tilde{J}_{x}^{YX} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x+1,0}^X + \theta_{x,0}\theta_{x,1}\theta_{x+1,0} \hat{\sigma}_{x,1}^Y \hat{\sigma}_{x+1,1}^X ) + \tilde{J}_{x}^{ZY} ( \hat{\sigma}_{x,0}^Z \hat{\sigma}_{x+1,0}^Y + \theta_{x,1}\theta_{x+1,0} \theta_{x+1,1} \hat{\sigma}_{x,1}^Z \hat{\sigma}_{x+1,1}^Y) \nonumber \\ && \qquad + \tilde{J}_{x}^{YZ} (\hat{\sigma}_{x,0}^Y \hat{\sigma}_{x+1,0}^Z + \theta_{x,0}\theta_{x,1}\theta_{x+1,1} \hat{\sigma}_{x,1}^Y \hat{\sigma}_{x+1,1}^Z) ] . \label{eq:H_leftright} \end{eqnarray} Here, $\hat{H}_h$ describes 1-body magnetic field terms, $\hat{H}_\updownarrow$ describes 2-local, 2-body interactions in the $y$-direction [i.e., between rails of the ladder in Fig. \ref{fig:products_of_Bell_pairs}(left)] and $\hat{H}_\leftrightarrow$ describes 2-local, 2-body interactions in the $x$-direction (i.e., between rungs of the ladder).
L000297	
L000298	This representation of the parent Hamiltonian, although clearly a linear combination of the annihilating terms in the right column of Table \ref{table:product_Bell_pairs}, is quite complicated. A much simpler representation is possible if we assume that $\theta_{x,y} = 1$ for all $(x,y)$. Then we can write the parent Hamiltonian as $\hat{H}^{\rm ladder-BP} = \hat{H}_0 + \hat{H}_1 + \hat{H}_\updownarrow$, where: \begin{eqnarray} \hat{H}_0 &=& \sum_{x=0}^{N_x - 1} \sum_{\mu \in \{ X,Y,Z \}} h_{x}^\mu \hat{\sigma}_{x,0}^\mu + \sum_{x=0}^{N_x - 1} \sum_{\mu,\nu \in \{ X,Y,Z \}} \tilde{J}_{x}^{\mu\nu} \hat{\sigma}_{x,0}^\mu \hat{\sigma}_{x+1,0}^\nu  , \label{eq:H_0} \end{eqnarray} is a 2-local, 2-body Hamiltonian along the bottom rail of the ladder ($y=0$), and \begin{eqnarray} \hat{H}_1 &=& - \mathcal{T}_y \hat{H}_0^* \mathcal{T}_y ,  \end{eqnarray} is the Hamiltonian along the top rail of the ladder ($y=1$). Here, $\mathcal{T}_y$ is the one-site translation operator in the $y$-direction (we assume periodic boundary conditions) and the complex conjugation is taken with respect to the computational basis. We note that \emph{any} traceless 2-local, 2-body Hamiltonian on an $N$ qubit chain can be written in the form of $\hat{H}_0$ in Eq. \ref{eq:H_0}. The Hamiltonian $\hat{H}_0$ on the bottom rail, and the Hamiltonian $\hat{H}_1 = - \mathcal{T}_y \hat{H}_0^* \mathcal{T}_y$ on the top rail are coupled by the interaction $\hat{H}_{\updownarrow}$ given in Eq. \ref{eq:H_updown}.
