L000426	\section{Stabilizer eigenstate of the PXP Hamiltonian} \label{app:PXP}
L000427	
L000428	The PXP Hamiltonian on a chain of $N$ qubits is: \begin{equation} \hat{H}^{\rm PXP} = \sum_{n=0}^{N-1} \hat{\mathcal{P}}_{n-1} \hat{\sigma}_n^X \hat{\mathcal{P}}_{n+1} , \end{equation} where $\hat{\mathcal{P}}_n = \frac{1}{2} (\hat{\mathbb{I}} - \hat{\sigma}_n^Z)$. Substituting the expression for $\hat{\mathcal{P}}_n$ into $\hat{H}^{\rm PXP}$ allows us to write the PXP Hamiltonian as a linear combination of Pauli strings: \begin{equation} \hat{H}^{\rm PXP} = \frac{1}{4} \sum_{n=0}^{N-1} ( \hat{\sigma}_n^X - \hat{\sigma}_n^X \hat{\sigma}_{n+1}^Z - \hat{\sigma}_{n-1}^Z \hat{\sigma}_n^X + \hat{\sigma}_{n-1}^Z \hat{\sigma}_n^X \hat{\sigma}_{n+1}^Z ) . \end{equation} It is known that the antipodal product of Bell pairs is an eigenstate of the PXP Hamiltonian \cite{Iva-25a, Chi-24a}, which we now show using our framework.
L000429	
L000430	The antipodal product of Bell pairs (Eq. \ref{eq:psi_antipodal_Bell}) has the stabilizer group given in Eq. \ref{eq:antipodal_Bell_stab}, which we repeat here for the reader's convenience:
L000431	\begin{equation} \mathcal{S}^{\rm antipodal-BP} = \langle \{ \hat{Q}_n , \hat{Q}_{n+N/2}  \}_{n=0}^{N/2 - 1} \rangle \quad {\rm where} \quad \hat{Q}_n \equiv \theta_{n} \hat{\sigma}_{n}^X \hat{\sigma}_{n+N/2}^X \quad {\rm and} \quad \hat{Q}_{n+N/2} \equiv \theta_{n+N/2} \hat{\sigma}_{n}^Z \hat{\sigma}_{n+N/2}^Z . \end{equation} Since $\hat{Q}_n = \theta_{n} \hat{\sigma}_{n}^X \hat{\sigma}_{n+N/2}^X$ is a $(2,1,1)$-factorizable stabilizer element, the antipodal product of Bell pairs is annihilated by the 1-local, 1-body operators: \begin{equation} \hat{\sigma}_{n}^X - \theta_{n} \hat{\sigma}_{n+N/2}^X , \quad n \in \{ 0,1,\hdots, N/2-1 \} . \label{eq:PXP_1body} \end{equation} Also, since the products of generators $\hat{Q}_n \hat{Q}_{n+N/2+1} = \theta_n \theta_{n+N/2+1} (\hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z) (\hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z)$ and $\hat{Q}_{n+1} \hat{Q}_{n+N/2} = \theta_{n+1} \theta_{n+N/2} (\hat{\sigma}_{n}^Z \hat{\sigma}_{n+1}^X) (\hat{\sigma}_{n+N/2}^Z \hat{\sigma}_{n+N/2+1}^X)$ are $(2,2,2)$-factorizable stabilizer elements, the antipodal product of Bell pairs is annihilated by the 2-local, 2-body operators: \begin{equation} \hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z - \theta_n \theta_{n+N/2+1} \hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z, \quad \hat{\sigma}_{n}^Z \hat{\sigma}_{n+1}^X - \theta_{n+1} \theta_{n+N/2} \hat{\sigma}_{n+N/2}^Z \hat{\sigma}_{n+N/2+1}^X , \quad n \in \{ 0,1,\hdots, N/2-1 \} . \label{eq:PXP_2body} \end{equation} Finally, the product of generators \begin{eqnarray} \hat{Q}_{n+N/2-1} \hat{Q}_n \hat{Q}_{n+N/2+1} &=& (\theta_{n+N/2-1} \hat{\sigma}_{n-1}^Z \hat{\sigma}_{n+N/2-1}^Z) (\theta_{n} \hat{\sigma}_{n}^X \hat{\sigma}_{n+N/2}^X) (\theta_{n+N/2+1} \hat{\sigma}_{n+1}^Z \hat{\sigma}_{n+N/2+1}^Z) \nonumber \\ &=& \theta_{n+N/2-1} \theta_{n} \theta_{n+N/2+1} (\hat{\sigma}_{n-1}^Z \hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z) (\hat{\sigma}_{n+N/2-1}^Z \hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z) \nonumber \end{eqnarray} is $(2,3,3)$-local, so that the antipodal product of Bell pairs is annihilated by the 3-local, 3-body operators: \begin{equation}  \hat{\sigma}_{n-1}^Z \hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z - \theta_{n+N/2-1} \theta_{n} \theta_{n+N/2+1} \hat{\sigma}_{n+N/2-1}^Z \hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z , \quad n \in \{ 0,1,\hdots, N/2-1 \} . \label{eq:PXP_3body} \end{equation}
L000432	
L000433	A linear combination of the terms in Eqs. \ref{eq:PXP_1body}, \ref{eq:PXP_2body} and \ref{eq:PXP_3body} gives a parent Hamiltonian: \begin{eqnarray} \hat{H} = \sum_{n=0}^{N/2 - 1} [&J_n^X& (\hat{\sigma}_{n}^X - \theta_{n} \hat{\sigma}_{n+N/2}^X) \nonumber \\ + &J_n^{XZ}& (\hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z - \theta_n \theta_{n+N/2+1} \hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z) \nonumber \\ + &J_n^{ZX}& (\hat{\sigma}_{n}^Z \hat{\sigma}_{n+1}^X - \theta_{n+1} \theta_{n+N/2} \hat{\sigma}_{n+N/2}^Z \hat{\sigma}_{n+N/2+1}^X) \nonumber \\ +  &J_n^{ZXZ}& (\hat{\sigma}_{n-1}^Z \hat{\sigma}_{n}^X \hat{\sigma}_{n+1}^Z - \theta_{n+N/2-1} \theta_{n} \theta_{n+N/2+1} \hat{\sigma}_{n+N/2-1}^Z \hat{\sigma}_{n+N/2}^X \hat{\sigma}_{n+N/2+1}^Z) ] . \end{eqnarray} for the antipodal product of Bell pairs, where $J_n^X$, $J_n^{XZ}$, $J_n^{ZX}$ and $J_n^{ZXZ}$ are arbitrary real parameters. If we chose the stabilizer phases $\theta_n = -1$ and $\theta_{n+N/2}=1$ for $n \in \{0,1,\hdots,N/2-1\}$, and also the Hamiltonian parameters $J_n^X = J_n^{ZXZ} = - J_n^{XZ} = - J_n^{ZX} = 1/4$, then the Hamiltonian simplifies to: \begin{equation} \hat{H} = \frac{1}{4} \sum_{n=0}^{N-1} (\hat{\sigma}_n^X - \hat{\sigma}_n^X \hat{\sigma}_{n+1}^Z - \hat{\sigma}_{n-1}^Z \hat{\sigma}_n^X + \hat{\sigma}_{n-1}^Z \hat{\sigma}_n^X \hat{\sigma}_{n+1}^Z) = \hat{H}^{\rm PXP} , \end{equation} which is the PXP Hamiltonian. Using Eq. \ref{eq:psi_antipodal_Bell}, the antipodal product of Bell pairs that is annihilated by $\hat{H}^{\rm PXP}$ is explicitly written as: \begin{eqnarray} \ket{\Psi^{\rm antipodal-BP}} &=& \bigotimes_{n=0}^{N/2-1} \ket{\psi (-1,1)}_{n,n+N/2} \nonumber \\ &=& \bigotimes_{n=0}^{N/2 - 1} \left[ \frac{1}{\sqrt{2}} (\ket{1}_n \ket{1}_{n+N/2} - \ket{-1}_n \ket{-1}_{n+N/2} ) \right] . \end{eqnarray}
L000434	This (volume-law entangled) exact QMBS of the PXP chain was already known from Refs. \cite{Iva-25a, Chi-24a}.
